begin;
with vip as (select v.user_id,row_number() over(order by v.user_id) rn from user_vip_memberships v where v.enabled and v.paid_until>now() and not exists(select 1 from bookings b where b.user_id=v.user_id)), picks as (select b.id,row_number() over(order by b.starts_at,b.id) rn from bookings b where b.status in ('confirmed','completed')), pair as (select p.id,v.user_id from picks p join vip v using(rn) where p.rn<=30)
update bookings b set user_id=pair.user_id,customer_name=pr.full_name,customer_phone=coalesce(pr.phone,b.customer_phone) from pair join profiles pr on pr.id=pair.user_id where b.id=pair.id;
commit;
select jsonb_build_object('orders',(select count(*) from bookings),'vip_with_orders',(select count(*) from user_vip_memberships v where v.enabled and v.paid_until>now() and exists(select 1 from bookings b where b.user_id=v.user_id)),'vip_without_orders',(select count(*) from user_vip_memberships v where v.enabled and v.paid_until>now() and not exists(select 1 from bookings b where b.user_id=v.user_id)));
